import React, { useState } from 'react';
import { Trash2, Plus, Users, Play, Clock, Layers, Calendar, FileText, Download } from 'lucide-react';

const addHours = (time, hours) => {
  const [h, m] = time.split(':').map(Number);
  const newDate = new Date();
  newDate.setHours(h + hours, m);
  return newDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true });
};

const DepartmentCard = ({ dept, onUpdate, onGenerate, globalSchedule = [], allDepartments = [] }) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const [localPreview, setLocalPreview] = useState([]);
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // --- GENERATOR UI STATES ---
  const [examDays, setExamDays] = useState(0); // Fixed: Starts at 0
  const [examDates, setExamDates] = useState([]);
  const [startTime, setStartTime] = useState("08:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(0); 
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");

  // --- INPUT STATES ---
  const [pName, setPName] = useState("");
  const [pDayStart, setPDayStart] = useState("");
  const [pDayEnd, setPDayEnd] = useState("");
  const [pTimeStart, setPTimeStart] = useState("08:00");
  const [pTimeEnd, setPTimeEnd] = useState("17:00");
  const [roomNum, setRoomNum] = useState("");

  const handleExamDayChange = (val) => {
    const num = parseInt(val) || 0; // Fixes the "12" string concatenation bug
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const exportToCSV = () => {
    if (localPreview.length === 0) return;
    const headers = ["Section,Date,Time,Room,Proctor,Subjects\n"];
    const rows = localPreview.map(row => 
      `${row.section},${row.exam_date},"${row.start_time}-${row.end_time}",${row.room},${row.proctor},"${row.subjects.join(' | ')}"`
    );
    const blob = new Blob([headers + rows.join("\n")], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${deptCode}_Year${selectedYear}_Schedule.csv`;
    a.click();
  };

  const handleGenerateClick = () => {
    const yearSubjects = subjects[selectedYear];
    if (yearSubjects.length === 0 || examDays === 0) return alert("Add subjects and set exam days!");

    // 1. SHUFFLE & SPLIT SUBJECTS
    const shuffled = [...yearSubjects].sort(() => Math.random() - 0.5);
    const dailySubjects = Array.from({ length: examDays }, () => []);
    shuffled.forEach((s, i) => dailySubjects[i % examDays].push(s));

    const finalGeneratedData = [];
    const previewData = [];

    for (let dayIdx = 0; dayIdx < examDays; dayIdx++) {
      const daySubs = dailySubjects[dayIdx];
      const currentDate = examDates[dayIdx];
      const duration = daySubs.length; 
      const endTime = addHours(startTime, duration);

      const roomPool = roomSource === "Global" ? allDepartments.flatMap(d => d.rooms) : rooms;
      const proctorPool = proctorSource === "Global" ? allDepartments.flatMap(d => d.proctors) : proctors;

      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`; // e.g. BSIS3A

        const selectedRoom = roomPool[s]; 
        const selectedProctor = proctorPool.find(p => 
          currentDate >= p.dayStart && currentDate <= p.dayEnd &&
          startTime >= p.timeStart && !globalSchedule.some(gs => gs.proctor === p.name && gs.exam_date === currentDate)
        );

        if (!selectedRoom || !selectedProctor) return alert("Resource shortage for " + sectionID);

        // BUNDLE SUBJECTS INTO ONE BLOCK
        previewData.push({
          section: sectionID,
          exam_date: currentDate,
          start_time: startTime,
          end_time: endTime,
          room: selectedRoom.number,
          proctor: selectedProctor.name,
          subjects: daySubs.map(sub => sub.code)
        });

        daySubs.forEach((sub, subIdx) => {
          finalGeneratedData.push({
            subject_code: sub.code,
            subject_name: sub.name,
            section: sectionID,
            year_level: selectedYear,
            dept_code: deptCode,
            exam_date: currentDate,
            start_time: addHours(startTime, subIdx),
            end_time: addHours(startTime, subIdx + 1),
            room: selectedRoom.number,
            proctor: selectedProctor.name
          });
        });
      }
    }
    setLocalPreview(previewData);
    onGenerate(finalGeneratedData, examDates);
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-xl border border-slate-200 overflow-hidden mb-10">
      <div className="bg-slate-900 p-6 text-white flex justify-between items-center">
        <h2 className="text-2xl font-black italic">{deptName} ({deptCode})</h2>
      </div>

      <div className="flex bg-slate-100 p-1">
        {['subjects', 'proctors', 'rooms', 'generate', 'preview'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`flex-1 py-3 text-[10px] font-black uppercase rounded-lg transition-all ${activeTab === t ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="p-8">
        {activeTab === 'generate' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 bg-slate-50 p-8 rounded-3xl border border-slate-200">
            <div className="space-y-4">
              <label className="text-[10px] font-black uppercase text-slate-400">Step 1: Exam Window</label>
              <input type="number" value={examDays} onChange={e => handleExamDayChange(e.target.value)} placeholder="Exam Days" className="w-full p-4 rounded-xl border-2 border-slate-200 font-black text-xl" />
              {examDates.map((d, i) => (
                <input key={i} type="date" value={d} onChange={e => { const nd = [...examDates]; nd[i] = e.target.value; setExamDates(nd); }} className="w-full p-2 rounded-lg border text-xs" />
              ))}
              <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full p-4 rounded-xl border-2 border-slate-200 font-black" />
            </div>
            <div className="space-y-4">
              <label className="text-[10px] font-black uppercase text-slate-400">Step 2: Sections & Rules</label>
              <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="w-full p-4 rounded-xl border-2 border-slate-200 font-black">
                {[1,2,3,4,5].map(y => <option key={y} value={y}>Year Level {y}</option>)}
              </select>
              <input type="number" value={sectionCount} onChange={e => setSectionCount(parseInt(e.target.value) || 0)} placeholder="Number of Sections" className="w-full p-4 rounded-xl border-2 border-slate-200 font-black" />
              <button onClick={handleGenerateClick} className="w-full bg-blue-600 text-white py-6 rounded-2xl font-black uppercase tracking-widest shadow-lg hover:bg-blue-700 transition-all">
                Run Allocation Engine
              </button>
            </div>
          </div>
        )}

        {activeTab === 'preview' && (
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <h3 className="font-black text-slate-800 uppercase tracking-tighter">Year {selectedYear} Generated View</h3>
              <button onClick={exportToCSV} className="flex items-center gap-2 bg-emerald-600 text-white px-4 py-2 rounded-lg text-[10px] font-black uppercase">
                <Download size={14}/> Export to Excel
              </button>
            </div>
            <div className="overflow-x-auto rounded-2xl border border-slate-200">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-900 text-white text-[10px] font-black uppercase">
                  <tr>
                    <th className="p-4">Section</th><th className="p-4">Date</th><th className="p-4">Time Window</th>
                    <th className="p-4">Room</th><th className="p-4">Proctor</th><th className="p-4">Subjects Bundled</th>
                  </tr>
                </thead>
                <tbody className="text-xs font-bold text-slate-600">
                  {localPreview.map((row, i) => (
                    <tr key={i} className="border-b hover:bg-blue-50">
                      <td className="p-4 text-blue-600">{row.section}</td>
                      <td className="p-4">{row.exam_date}</td>
                      <td className="p-4 bg-slate-50">{row.start_time} - {row.end_time}</td>
                      <td className="p-4 font-black">{row.room}</td>
                      <td className="p-4">{row.proctor}</td>
                      <td className="p-4 text-[9px] uppercase italic">{row.subjects.join(', ')}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {localPreview.length === 0 && <div className="p-20 text-center text-slate-300 font-black uppercase">No schedule generated yet.</div>}
            </div>
          </div>
        )}

        {/* --- OTHER TABS (SUBJECTS, PROCTORS, ROOMS) RENDERED SAME AS BEFORE --- */}
        {activeTab === 'subjects' && (
          <div className="space-y-4">
             <div className="grid grid-cols-4 gap-2 bg-slate-50 p-4 rounded-2xl">
              <select className="p-2 rounded-lg text-xs font-bold" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>{[1,2,3,4,5].map(y => <option key={y} value={y}>Year {y}</option>)}</select>
              <input id={`sC-${deptId}`} placeholder="CODE" className="p-2 rounded-lg text-xs font-bold" />
              <input id={`sN-${deptId}`} placeholder="NAME" className="p-2 rounded-lg text-xs font-bold" />
              <button onClick={() => {
                const c = document.getElementById(`sC-${deptId}`).value; const n = document.getElementById(`sN-${deptId}`).value;
                if(c && n) {
                    onUpdate('subjects', { ...subjects, [selectedYear]: [...subjects[selectedYear], { code: c.toUpperCase(), name: n }] });
                    document.getElementById(`sC-${deptId}`).value = ''; document.getElementById(`sN-${deptId}`).value = '';
                }
              }} className="bg-blue-600 text-white rounded-lg"><Plus /></button>
            </div>
            <div className="grid grid-cols-2 gap-2">{subjects[selectedYear]?.map((s, i) => (<div key={i} className="flex justify-between p-3 bg-white border rounded-xl items-center font-black text-xs">{s.code}: {s.name} <button onClick={() => onUpdate('subjects', {...subjects, [selectedYear]: subjects[selectedYear].filter((_,idx)=>idx!==i)}) }><Trash2 size={14} className="text-slate-300" /></button></div>))}</div>
          </div>
        )}

        {activeTab === 'proctors' && (
          <div className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-5 gap-2 bg-emerald-50 p-4 rounded-2xl">
              <input value={pName} onChange={e=>setPName(e.target.value)} placeholder="NAME" className="p-2 rounded-lg text-xs font-bold col-span-1" />
              <input type="date" value={pDayStart} onChange={e=>setPDayStart(e.target.value)} className="p-2 rounded-lg text-[10px]" />
              <input type="date" value={pDayEnd} onChange={e=>setPDayEnd(e.target.value)} className="p-2 rounded-lg text-[10px]" />
              <input type="time" value={pTimeStart} onChange={e=>setPTimeStart(e.target.value)} className="p-2 rounded-lg text-[10px]" />
              <button onClick={() => { onUpdate('proctors', [...proctors, { id: Date.now(), name: pName.toUpperCase(), dayStart: pDayStart, dayEnd: pDayEnd, timeStart: pTimeStart, timeEnd: "17:00" }]); setPName(""); }} className="bg-emerald-600 text-white rounded-lg text-[10px] font-black uppercase">Add</button>
            </div>
            <div className="grid grid-cols-2 gap-2">{proctors.map(p => (<div key={p.id} className="p-3 border rounded-xl flex justify-between items-center text-xs font-bold uppercase">{p.name} <Trash2 size={14} className="text-slate-300 cursor-pointer" onClick={() => onUpdate('proctors', proctors.filter(item => item.id !== p.id))}/></div>))}</div>
          </div>
        )}

        {activeTab === 'rooms' && (
          <div className="space-y-4">
            <div className="flex gap-2">
                <input value={roomNum} onChange={e=>setRoomNum(e.target.value)} placeholder="ROOM #" className="flex-1 p-3 border rounded-xl text-xs font-bold" />
                <button onClick={() => { if(roomNum){ onUpdate('rooms', [...rooms, {id: Date.now(), number: roomNum.toUpperCase(), type: 'Department'}]); setRoomNum(""); } }} className="bg-amber-600 text-white px-4 rounded-xl text-[10px] font-black uppercase">Dept</button>
            </div>
            <div className="grid grid-cols-6 gap-2">{rooms.map(r => (<div key={r.id} className="p-4 bg-slate-50 rounded-xl text-center font-black">{r.number}</div>))}</div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
